179	    public void onBindViewHolder(@NonNull RecyclerView.ViewHolder holder, int position) {
180	        Context ctx = holder.itemView.getContext();
181	        if (holder instanceof HeaderViewHolder) {
182	            final HeaderViewHolder headerViewHolder = (HeaderViewHolder) holder;
183	
184	            if (story.isLink && story.url != null) {
185	                try {
186	                    headerViewHolder.urlView.setText("(" + Utils.getDomainName(story.url) + ")");
187	                } catch (Exception e) {
188	                    e.printStackTrace();
189	                }
190	            }
191	
192	            headerViewHolder.headerView.setClickable(story.isLink);
193	            headerViewHolder.linkImage.setVisibility(story.isLink && !story.isComment ? View.VISIBLE : View.GONE);
194	            headerViewHolder.textView.setVisibility(story.text == null ? View.GONE : View.VISIBLE);
195	
196	            if (story.text != null) {
197	                headerViewHolder.textView.setHtml(story.text);
198	            }
199	
200	            if (story.pollOptionArrayList != null) {
201	                headerViewHolder.pollLayout.setVisibility(View.VISIBLE);
202	                headerViewHolder.pollLayout.removeAllViews();
203	                for (int i = 0; i < story.pollOptionArrayList.size(); i++) {
204	                    PollOption pollOption = story.pollOptionArrayList.get(i);
205	                    if (pollOption.loaded) {
206	                        MaterialButton materialButton = new MaterialButton(ctx, null, com.google.android.material.R.attr.materialButtonOutlinedStyle);
207	                        materialButton.setText(pollOption.text + " (" + pollOption.points + (pollOption.points == 1 ? " point" : " points") + ")");
208	
209	                        materialButton.setTextColor(Utils.getColorViaAttr(ctx, R.attr.storyColorNormal));
210	
211	                        materialButton.setOnClickListener(new View.OnClickListener() {
212	                            @Override
213	                            public void onClick(View view) {
214	                                UserActions.upvote(ctx, pollOption.id, fragmentManager);
215	                            }
216	                        });
217	                        headerViewHolder.pollLayout.addView(materialButton);
218	                    } else {
219	                        ProgressBar progressBar = new ProgressBar(ctx);
220	                        headerViewHolder.pollLayout.addView(progressBar);
221	                    }
222	                }
223	            } else {
224	                headerViewHolder.pollLayout.setVisibility(View.GONE);
225	            }
226	
227	            if (!TextUtils.isEmpty(story.pdfTitle)) {
228	                SpannableStringBuilder sb = new SpannableStringBuilder(story.pdfTitle + " ");
229	                ImageSpan imageSpan = new ImageSpan(ctx, R.drawable.ic_action_pdf_large);
230	                sb.setSpan(imageSpan, story.pdfTitle.length(), story.pdfTitle.length() + 1, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
231	
232	                headerViewHolder.titleView.setText(sb);
233	            } else {
234	                headerViewHolder.titleView.setText(story.title);
235	            }
236	
237	            if (story.loaded) {
238	                headerViewHolder.metaVotes.setText(String.valueOf(story.score));
239	                headerViewHolder.metaComments.setText(String.valueOf(story.descendants));
240	                headerViewHolder.metaTime.setText(story.getTimeFormatted());
241	                headerViewHolder.metaBy.setText(story.by);
242	            }
243	
244	            headerViewHolder.metaContainer.setVisibility(story.loaded ? View.VISIBLE : View.GONE);
245	            headerViewHolder.urlView.setVisibility(story.isLink ? View.VISIBLE : View.GONE);
246	            headerViewHolder.metaVotes.setVisibility(story.isComment ? View.GONE : View.VISIBLE);
247	            headerViewHolder.metaVotesIcon.setVisibility(story.isComment ? View.GONE : View.VISIBLE);
248	
249	            FontUtils.setTypeface(headerViewHolder.titleView, true, 26, 26, 23, 26, 24, 26);
250	            FontUtils.setTypeface(headerViewHolder.textView, false, preferredTextSize);
251	
252	            if (loadingFailed) {
253	                headerViewHolder.loadingIndicator.setVisibility(View.GONE);
254	                headerViewHolder.emptyView.setVisibility(View.GONE);
255	            } else {
256	                if (commentsLoaded) {
257	                    headerViewHolder.loadingIndicator.setVisibility(View.GONE);
258	                    headerViewHolder.emptyView.setVisibility(story.descendants > 0 ? View.GONE : View.VISIBLE);
259	                } else {
260	                    headerViewHolder.loadingIndicator.setVisibility(View.VISIBLE);
261	                    headerViewHolder.emptyView.setVisibility(View.GONE);
262	                }
263	            }
264	
265	            int actionContainerPadding = Math.round(headerViewHolder.actionsContainer.getResources().getDimension(R.dimen.comments_header_action_padding));
266	            headerViewHolder.actionsContainer.setPadding(actionContainerPadding, 0, actionContainerPadding, 0);
267	
268	            headerViewHolder.favicon.setVisibility(showThumbnail ? View.VISIBLE : View.GONE);
269	            headerViewHolder.linkInfoContainer.setVisibility(!story.isComment && story.isLink ? View.VISIBLE : View.GONE);
270	
271	            if (showThumbnail && !TextUtils.isEmpty(story.url)) {
272	                FaviconLoader.loadFavicon(story.url, headerViewHolder.favicon, ctx, faviconProvider);
273	            }
274	
275	            headerViewHolder.bookmarkIcon.setBackgroundResource(
276	                    Utils.isBookmarked(ctx, story.id) ? R.drawable.ic_action_bookmark_filled : R.drawable.ic_action_bookmark_border);
277	
278	            headerViewHolder.bookmarkLayout.setOnClickListener(new View.OnClickListener() {
279	                @Override
280	                public void onClick(View view) {
281	                    boolean wasBookmarked = Utils.isBookmarked(view.getContext(), story.id);
282	
283	                    if (wasBookmarked) {
284	                        Utils.removeBookmark(view.getContext(), story.id);
285	                    } else {
286	                        Utils.addBookmark(view.getContext(), story.id);
287	                    }
288	
289	                    notifyItemChanged(0);
290	
291	                    Snackbar snackbar = Snackbar.make(
292	                            view,
293	                            wasBookmarked ? "Removed bookmark" : "Bookmarked post",
294	                            Snackbar.LENGTH_SHORT);
295	
296	                    ViewCompat.setElevation(snackbar.getView(), Utils.pxFromDp(view.getResources(), 24));
