300	                    }
301	
302	                    snackbar.show();
303	                }
304	            });
305	
306	            headerViewHolder.emptyViewText.setText(story.isComment ? "No replies" : "No comments");
307	            headerViewHolder.bookmarkLayoutParent.setVisibility(story.isComment ? View.GONE : View.VISIBLE);
