312	
313	        } else if (holder instanceof ItemViewHolder) {
314	            final ItemViewHolder itemViewHolder = (ItemViewHolder) holder;
315	            itemViewHolder.comment = comments.get(position);
316	
317	            LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT);
