659	    public int getIndexOfLastChild(int commentDepth, int pos) {
660	        int lastChildIndex = pos;
661	        for (int i = pos + 1; i < comments.size(); i++) {
662	            if (comments.get(i).depth > commentDepth) {
663	                lastChildIndex = i;
664	            } else {
665	                return lastChildIndex;
666	            }
667	        }
668	        return lastChildIndex;
669	    }
