671	    private boolean shouldShow(Comment comment) {
672	        /*
673	        * Try to call shouldShow() on the parent if parent is expanded
674	        * if parent is not expanded the return false.
675	        *
676	        * If parent is -1 (top level) always show
677	        * */
678	
679	        if (comment.parent == -1) {
680	            return true;
681	        }
682	
683	        for (Comment c : comments) {
684	            if (c.id == comment.parent) {
685	                if (c.expanded) {
686	                    return shouldShow(c);
687	                } else {
688	                    return false;
689	                }
690	            }
691	        }
692	        return true;
693	    }
