160	    private void replaceQuoteSpans(Spanned spanned) {
161	
162	        Spannable spannable = (Spannable) spanned;
163	        QuoteSpan[] quoteSpans = spannable.getSpans(0, spannable.length() - 1, QuoteSpan.class);
164	        for (QuoteSpan quoteSpan : quoteSpans) {
165	            int start = spannable.getSpanStart(quoteSpan);
166	            int end = spannable.getSpanEnd(quoteSpan);
167	            int flags = spannable.getSpanFlags(quoteSpan);
168	            spannable.removeSpan(quoteSpan);
169	            spannable.setSpan(new DesignQuoteSpan(
170	                            blockQuoteBackgroundColor,
171	                            blockQuoteStripColor,
172	                            blockQuoteStripWidth,
173	                            blockQuoteGap),
174	                    start,
175	                    end,
176	                    flags);
177	        }
178	    }
