31	/**
32	 * <p/>
33	 * A {@link android.widget.TextView} that insert spaces around its text spans where needed to prevent
34	 * {@link IndexOutOfBoundsException} in {@link #onMeasure(int, int)} on Jelly Bean.
35	 * <p/>
36	 * When {@link #onMeasure(int, int)} throws an exception, we try to fix the text by adding spaces
37	 * around spans, until it works again. We then try removing some of the added spans, to minimize the
38	 * insertions.
39	 * <p/>
40	 * The fix is time consuming (a few ms, it depends on the size of your text), but it should only
41	 * happen once per text change.
42	 * <p/>
43	 * See http://code.google.com/p/android/issues/detail?id=35466
44	 * <p/>
45	 * From https://gist.github.com/pyricau/3424004 with fix from comments
46	 */
47	public class JellyBeanSpanFixTextView extends androidx.appcompat.widget.AppCompatTextView {
48	
49	    private static class FixingResult {
50	        public final boolean fixed;
51	        public final List<Object> spansWithSpacesBefore;
52	        public final List<Object> spansWithSpacesAfter;
53	
54	        public static FixingResult fixed(List<Object> spansWithSpacesBefore,
55	                                         List<Object> spansWithSpacesAfter) {
56	            return new FixingResult(true, spansWithSpacesBefore, spansWithSpacesAfter);
57	        }
58	
59	        public static FixingResult notFixed() {
60	            return new FixingResult(false, null, null);
61	        }
62	
63	        private FixingResult(boolean fixed, List<Object> spansWithSpacesBefore,
64	                             List<Object> spansWithSpacesAfter) {
65	            this.fixed = fixed;
66	            this.spansWithSpacesBefore = spansWithSpacesBefore;
67	            this.spansWithSpacesAfter = spansWithSpacesAfter;
68	        }
69	    }
70	
71	    public JellyBeanSpanFixTextView(Context context, AttributeSet attrs, int defStyle) {
72	        super(context, attrs, defStyle);
73	    }
74	
75	    public JellyBeanSpanFixTextView(Context context, AttributeSet attrs) {
76	        super(context, attrs);
77	    }
78	
79	    public JellyBeanSpanFixTextView(Context context) {
80	        super(context);
81	    }
82	
83	    @Override
84	    protected void onMeasure(int widthMeasureSpec, int heightMeasureSpec) {
85	        try {
86	            super.onMeasure(widthMeasureSpec, heightMeasureSpec);
87	        } catch (IndexOutOfBoundsException e) {
88	            fixOnMeasure(widthMeasureSpec, heightMeasureSpec);
89	        }
90	    }
91	
92	    /**
93	     * If possible, fixes the Spanned text by adding spaces around spans when needed.
94	     */
95	    private void fixOnMeasure(int widthMeasureSpec, int heightMeasureSpec) {
96	        CharSequence text = getText();
97	        if (text instanceof Spanned) {
98	            SpannableStringBuilder builder = new SpannableStringBuilder(text);
99	            fixSpannedWithSpaces(builder, widthMeasureSpec, heightMeasureSpec);
100	        } else {
101	            if (HtmlTextView.DEBUG) {
102	                Log.d(HtmlTextView.TAG, "The text isn't a Spanned");
103	            }
104	            fallbackToString(widthMeasureSpec, heightMeasureSpec);
105	        }
106	    }
107	
108	    /**
109	     * Add spaces around spans until the text is fixed, and then removes the unneeded spaces
110	     */
111	    private void fixSpannedWithSpaces(SpannableStringBuilder builder, int widthMeasureSpec,
112	                                      int heightMeasureSpec) {
113	        long startFix = System.currentTimeMillis();
114	
115	        FixingResult result = addSpacesAroundSpansUntilFixed(builder, widthMeasureSpec,
116	                heightMeasureSpec);
117	
118	        if (result.fixed) {
119	            removeUnneededSpaces(widthMeasureSpec, heightMeasureSpec, builder, result);
120	        } else {
121	            fallbackToString(widthMeasureSpec, heightMeasureSpec);
122	        }
123	
124	        if (HtmlTextView.DEBUG) {
125	            long fixDuration = System.currentTimeMillis() - startFix;
126	            Log.d(HtmlTextView.TAG, "fixSpannedWithSpaces() duration in ms: " + fixDuration);
127	        }
128	    }
129	
130	    private FixingResult addSpacesAroundSpansUntilFixed(SpannableStringBuilder builder,
131	                                                        int widthMeasureSpec, int heightMeasureSpec) {
132	
133	        Object[] spans = builder.getSpans(0, builder.length(), Object.class);
134	        List<Object> spansWithSpacesBefore = new ArrayList<>(spans.length);
135	        List<Object> spansWithSpacesAfter = new ArrayList<>(spans.length);
136	
137	        for (Object span : spans) {
138	            int spanStart = builder.getSpanStart(span);
139	            if (isNotSpace(builder, spanStart - 1)) {
140	                builder.insert(spanStart, " ");
141	                spansWithSpacesBefore.add(span);
142	            }
143	
144	            int spanEnd = builder.getSpanEnd(span);
145	            if (isNotSpace(builder, spanEnd)) {
146	                builder.insert(spanEnd, " ");
147	                spansWithSpacesAfter.add(span);
148	            }
149	
150	            try {
151	                setTextAndMeasure(builder, widthMeasureSpec, heightMeasureSpec);
152	                return FixingResult.fixed(spansWithSpacesBefore, spansWithSpacesAfter);
153	            } catch (IndexOutOfBoundsException ignored) {
154	            }
155	        }
156	        if (HtmlTextView.DEBUG) {
157	            Log.d(HtmlTextView.TAG, "Could not fix the Spanned by adding spaces around spans");
158	        }
159	        return FixingResult.notFixed();
160	    }
161	
162	    private boolean isNotSpace(CharSequence text, int where) {
163	        return where < 0 || where >= text.length() || text.charAt(where) != ' ';
164	    }
165	
166	    @SuppressLint("WrongCall")
167	    private void setTextAndMeasure(CharSequence text, int widthMeasureSpec, int heightMeasureSpec) {
168	        setText(text);
169	        super.onMeasure(widthMeasureSpec, heightMeasureSpec);
170	    }
171	
172	    @SuppressLint("WrongCall")
173	    private void removeUnneededSpaces(int widthMeasureSpec, int heightMeasureSpec,
174	                                      SpannableStringBuilder builder, FixingResult result) {
175	
176	        for (Object span : result.spansWithSpacesAfter) {
177	            int spanEnd = builder.getSpanEnd(span);
178	            builder.delete(spanEnd, spanEnd + 1);
179	            try {
180	                setTextAndMeasure(builder, widthMeasureSpec, heightMeasureSpec);
181	            } catch (IndexOutOfBoundsException ignored) {
182	                builder.insert(spanEnd, " ");
183	            }
184	        }
185	
186	        boolean needReset = true;
187	        for (Object span : result.spansWithSpacesBefore) {
188	            int spanStart = builder.getSpanStart(span);
189	            builder.delete(spanStart - 1, spanStart);
190	            try {
191	                setTextAndMeasure(builder, widthMeasureSpec, heightMeasureSpec);
192	                needReset = false;
193	            } catch (IndexOutOfBoundsException ignored) {
194	                needReset = true;
195	                int newSpanStart = spanStart - 1;
196	                builder.insert(newSpanStart, " ");
197	            }
198	        }
199	
200	        if (needReset) {
201	            setText(builder);
202	            super.onMeasure(widthMeasureSpec, heightMeasureSpec);
203	        }
204	    }
205	
206	    private void fallbackToString(int widthMeasureSpec, int heightMeasureSpec) {
207	        if (HtmlTextView.DEBUG) {
208	            Log.d(HtmlTextView.TAG, "Fallback to unspanned text");
209	        }
210	        String fallbackText = getText().toString();
211	        setTextAndMeasure(fallbackText, widthMeasureSpec, heightMeasureSpec);
212	    }
