44	    public static final String UNORDERED_LIST = "HTML_TEXTVIEW_ESCAPED_UL_TAG";
45	    public static final String ORDERED_LIST = "HTML_TEXTVIEW_ESCAPED_OL_TAG";
46	    public static final String LIST_ITEM = "HTML_TEXTVIEW_ESCAPED_LI_TAG";
47	    public static final String A_ITEM = "HTML_TEXTVIEW_ESCAPED_A_TAG";
48	    public static final String PLACEHOLDER_ITEM = "HTML_TEXTVIEW_ESCAPED_PLACEHOLDER";
