53	    /**
54	     * Newer versions of the Android SDK's {@link Html.TagHandler} handles &lt;ul&gt; and &lt;li&gt;
55	     * tags itself which means they never get delegated to this class. We want to handle the tags
56	     * ourselves so before passing the string html into Html.fromHtml(), we can use this method to
57	     * replace the &lt;ul&gt; and &lt;li&gt; tags with tags of our own.
58	     *
59	     * @param html String containing HTML, for example: "<b>Hello world!</b>"
60	     * @return html with replaced <ul> and <li> tags
61	     * @see <a href="https://github.com/android/platform_frameworks_base/commit/8b36c0bbd1503c61c111feac939193c47f812190">Specific Android SDK Commit</a>
62	     */
63	    String overrideTags(@Nullable String html) {
64	
65	        if (html == null) return null;
66	        html = "<" + PLACEHOLDER_ITEM + "></" + PLACEHOLDER_ITEM + ">" + html;
67	        html = html.replace("<ul", "<" + UNORDERED_LIST);
68	        html = html.replace("</ul>", "</" + UNORDERED_LIST + ">");
69	        html = html.replace("<ol", "<" + ORDERED_LIST);
70	        html = html.replace("</ol>", "</" + ORDERED_LIST + ">");
71	        html = html.replace("<li", "<" + LIST_ITEM);
72	        html = html.replace("</li>", "</" + LIST_ITEM + ">");
73	        html = html.replace("<a", "<" + A_ITEM);
74	        html = html.replace("</a>", "</" + A_ITEM + ">");
75	
76	        return html;
77	    }
