79	    /**
80	     * Keeps track of lists (ol, ul). On bottom of Stack is the outermost list
81	     * and on top of Stack is the most nested list
82	     */
83	    Stack<String> lists = new Stack<>();
84	    /**
85	     * Tracks indexes of ordered lists so that after a nested list ends
86	     * we can continue with correct index of outer list
87	     */
88	    Stack<Integer> olNextIndex = new Stack<>();
89	    /**
90	     * List indentation in pixels. Nested lists use multiple of this.
91	     */
92	    /**
93	     * Running HTML table string based off of the root table tag. Root table tag being the tag which
94	     * isn't embedded within any other table tag. Example:
95	     * <!-- This is the root level opening table tag. This is where we keep track of tables. -->
96	     * <table>
97	     * ...
98	     * <table> <!-- Non-root table tags -->
99	     * ...
100	     * </table>
101	     * ...
102	     * </table>
103	     * <!-- This is the root level closing table tag and the end of the string we track. -->
104	     */
105	    StringBuilder tableHtmlBuilder = new StringBuilder();
106	    /**
107	     * Tells us which level of table tag we're on; ultimately used to find the root table tag.
108	     */
109	    int tableTagLevel = 0;
