112	    private static final int defaultIndent = 10;
113	    private static final int defaultListItemIndent = defaultIndent * 2;
114	    private static final BulletSpan defaultBullet = new BulletSpan(defaultIndent);
115	    private ClickableTableSpan clickableTableSpan;
