156	    @Override
157	    public boolean handleTag(boolean opening, String tag, Editable output, Attributes attributes) {
158	        if (opening) {
159	            // opening tag
160	            if (HtmlTextView.DEBUG) {
161	                Log.d(HtmlTextView.TAG, "opening, output: " + output.toString());
162	            }
163	
164	            if (tag.equalsIgnoreCase(UNORDERED_LIST)) {
165	                lists.push(tag);
166	            } else if (tag.equalsIgnoreCase(ORDERED_LIST)) {
167	                lists.push(tag);
168	                olNextIndex.push(1);
169	            } else if (tag.equalsIgnoreCase(LIST_ITEM)) {
170	                if (output.length() > 0 && output.charAt(output.length() - 1) != '\n') {
171	                    output.append("\n");
172	                }
173	                if (!lists.isEmpty()) {
174	                    String parentList = lists.peek();
175	                    if (parentList.equalsIgnoreCase(ORDERED_LIST)) {
176	                        start(output, new Ol());
177	                        olNextIndex.push(olNextIndex.pop() + 1);
178	                    } else if (parentList.equalsIgnoreCase(UNORDERED_LIST)) {
179	                        start(output, new Ul());
180	                    }
181	                }
182	            } else if (tag.equalsIgnoreCase(A_ITEM)) {
183	                final String href = attributes != null ? attributes.getValue("href") : null;
184	                start(output, new A(output.toString(), href));
185	            } else if (tag.equalsIgnoreCase("code")) {
186	                start(output, new Code());
187	            } else if (tag.equalsIgnoreCase("center")) {
188	                start(output, new Center());
189	            } else if (tag.equalsIgnoreCase("s") || tag.equalsIgnoreCase("strike")) {
190	                start(output, new Strike());
191	            } else if (tag.equalsIgnoreCase("table")) {
192	                start(output, new Table());
193	                if (tableTagLevel == 0) {
194	                    tableHtmlBuilder = new StringBuilder();
195	                    // We need some text for the table to be replaced by the span because
196	                    // the other tags will remove their text when their text is extracted
197	                    output.append("table placeholder");
198	                }
199	
200	                tableTagLevel++;
201	            } else if (tag.equalsIgnoreCase("tr")) {
202	                start(output, new Tr());
203	            } else if (tag.equalsIgnoreCase("th")) {
204	                start(output, new Th());
205	            } else if (tag.equalsIgnoreCase("td")) {
206	                start(output, new Td());
207	            } else {
208	                return false;
209	            }
210	        } else {
211	            // closing tag
212	            if (HtmlTextView.DEBUG) {
213	                Log.d(HtmlTextView.TAG, "closing, output: " + output.toString());
214	            }
215	
216	            if (tag.equalsIgnoreCase(UNORDERED_LIST)) {
217	                lists.pop();
218	            } else if (tag.equalsIgnoreCase(ORDERED_LIST)) {
219	                lists.pop();
220	                olNextIndex.pop();
221	            } else if (tag.equalsIgnoreCase(LIST_ITEM)) {
222	                if (!lists.isEmpty()) {
223	                    int listItemIndent = (userGivenIndent > -1) ? (userGivenIndent * 2) : defaultListItemIndent;
224	                    if (lists.peek().equalsIgnoreCase(UNORDERED_LIST)) {
225	                        if (output.length() > 0 && output.charAt(output.length() - 1) != '\n') {
226	                            output.append("\n");
227	                        }
228	                        // Nested BulletSpans increases distance between bullet and text, so we must prevent it.
229	                        int indent = (userGivenIndent > -1) ? userGivenIndent : defaultIndent;
230	                        BulletSpan bullet = (userGivenIndent > -1) ? new BulletSpan(userGivenIndent) : defaultBullet;
231	                        if (lists.size() > 1) {
232	                            indent = indent - bullet.getLeadingMargin(true);
233	                            if (lists.size() > 2) {
234	                                // This get's more complicated when we add a LeadingMarginSpan into the same line:
235	                                // we have also counter it's effect to BulletSpan
236	                                indent -= (lists.size() - 2) * listItemIndent;
237	                            }
238	                        }
239	                        BulletSpan newBullet = new BulletSpan(indent);
240	                        end(output, Ul.class, false,
241	                                new LeadingMarginSpan.Standard(listItemIndent * (lists.size() - 1)),
242	                                newBullet);
243	                    } else if (lists.peek().equalsIgnoreCase(ORDERED_LIST)) {
244	                        if (output.length() > 0 && output.charAt(output.length() - 1) != '\n') {
245	                            output.append("\n");
246	                        }
247	
248	                        // Nested NumberSpans increases distance between number and text, so we must prevent it.
249	                        int indent = (userGivenIndent > -1) ? userGivenIndent : defaultIndent;
250	                        NumberSpan span = new NumberSpan(indent, olNextIndex.lastElement() - 1);
251	                        if (lists.size() > 1) {
252	                            indent = indent - span.getLeadingMargin(true);
253	                            if (lists.size() > 2) {
254	                                // As with BulletSpan, we need to compensate for the spacing after the number.
255	                                indent -= (lists.size() - 2) * listItemIndent;
256	                            }
257	                        }
258	                        NumberSpan numberSpan = new NumberSpan(indent, olNextIndex.lastElement() - 1);
259	                        end(output, Ol.class, false,
260	                                new LeadingMarginSpan.Standard(listItemIndent * (lists.size() - 1)),
261	                                numberSpan);
262	                    }
263	                }
264	            } else if (tag.equalsIgnoreCase(A_ITEM)) {
265	                final Object a = getLast(output, A.class);
266	                final int spanStart = output.getSpanStart(a);
267	                final int spanEnd = output.length();
268	                final String href = a instanceof A ? ((A) a).href : null;
269	                final String spannedText = output.subSequence(spanStart, spanEnd).toString();
270	                end(output, A.class, false, new URLSpan(href) {
271	                    @Override
272	                    public void onClick(View widget) {
273	                        if (onClickATagListenerProvider != null && widget != null) {
274	                            boolean clickConsumed = onClickATagListenerProvider.provideTagClickListener().onClick(widget, spannedText, getURL());
275	                            if (!clickConsumed) {
276	                                super.onClick(widget);
277	                            }
278	                        }
279	                    }
280	                });
281	            } else if (tag.equalsIgnoreCase("code")) {
282	                end(output, Code.class, false, new TypefaceSpan("monospace"));
283	            } else if (tag.equalsIgnoreCase("center")) {
284	                end(output, Center.class, true, new AlignmentSpan.Standard(Layout.Alignment.ALIGN_CENTER));
285	            } else if (tag.equalsIgnoreCase("s") || tag.equalsIgnoreCase("strike")) {
286	                end(output, Strike.class, false, new StrikethroughSpan());
287	            } else if (tag.equalsIgnoreCase("table")) {
288	                tableTagLevel--;
289	
290	                // When we're back at the root-level table
291	                if (tableTagLevel == 0) {
292	                    final String tableHtml = tableHtmlBuilder.toString();
293	
294	                    ClickableTableSpan myClickableTableSpan = null;
295	                    if (clickableTableSpan != null) {
296	                        myClickableTableSpan = clickableTableSpan.newInstance();
297	                        myClickableTableSpan.setTableHtml(tableHtml);
298	                    }
299	
300	                    DrawTableLinkSpan myDrawTableLinkSpan = null;
301	                    if (drawTableLinkSpan != null) {
302	                        myDrawTableLinkSpan = drawTableLinkSpan.newInstance();
303	                    }
304	
305	                    end(output, Table.class, false, myDrawTableLinkSpan, myClickableTableSpan);
306	                } else {
307	                    end(output, Table.class, false);
308	                }
309	            } else if (tag.equalsIgnoreCase("tr")) {
310	                end(output, Tr.class, false);
311	            } else if (tag.equalsIgnoreCase("th")) {
312	                end(output, Th.class, false);
313	            } else if (tag.equalsIgnoreCase("td")) {
314	                end(output, Td.class, false);
315	            } else {
316	                return false;
317	            }
318	        }
319	
320	        storeTableTags(opening, tag);
321	        return true;
322	    }
