324	    /**
325	     * If we're arriving at a table tag or are already within a table tag, then we should store it
326	     * the raw HTML for our ClickableTableSpan
327	     */
328	    private void storeTableTags(boolean opening, String tag) {
329	        if (tableTagLevel > 0 || tag.equalsIgnoreCase("table")) {
330	            tableHtmlBuilder.append("<");
331	            if (!opening) {
332	                tableHtmlBuilder.append("/");
333	            }
334	            tableHtmlBuilder
335	                    .append(tag.toLowerCase())
336	                    .append(">");
337	        }
338	    }
