340	    /**
341	     * Mark the opening tag by using private classes
342	     */
343	    private void start(Editable output, Object mark) {
344	        int len = output.length();
345	        output.setSpan(mark, len, len, Spannable.SPAN_MARK_MARK);
346	
347	        if (HtmlTextView.DEBUG) {
348	            Log.d(HtmlTextView.TAG, "len: " + len);
349	        }
350	    }
351	
352	    /**
353	     * Modified from {@link android.text.Html}
354	     */
355	    private void end(Editable output, Class kind, boolean paragraphStyle, Object... replaces) {
356	        Object obj = getLast(output, kind);
357	        // start of the tag
358	        int where = output.getSpanStart(obj);
359	        // end of the tag
360	        int len = output.length();
361	
362	        // If we're in a table, then we need to store the raw HTML for later
363	        if (tableTagLevel > 0) {
364	            final CharSequence extractedSpanText = extractSpanText(output, kind);
365	            tableHtmlBuilder.append(extractedSpanText);
366	        }
367	
368	        output.removeSpan(obj);
369	
370	        if (where != len) {
371	            int thisLen = len;
372	            // paragraph styles like AlignmentSpan need to end with a new line!
373	            if (paragraphStyle) {
374	                output.append("\n");
375	                thisLen++;
376	            }
377	            for (Object replace : replaces) {
378	                output.setSpan(replace, where, thisLen, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
379	            }
380	
381	            if (HtmlTextView.DEBUG) {
382	                Log.d(HtmlTextView.TAG, "where: " + where);
383	                Log.d(HtmlTextView.TAG, "thisLen: " + thisLen);
384	            }
385	        }
386	    }
387	
388	    /**
389	     * Returns the text contained within a span and deletes it from the output string
390	     */
391	    private CharSequence extractSpanText(Editable output, Class kind) {
392	        final Object obj = getLast(output, kind);
393	        // start of the tag
394	        final int where = output.getSpanStart(obj);
395	        // end of the tag
396	        final int len = output.length();
397	
398	        final CharSequence extractedSpanText = output.subSequence(where, len);
399	        output.delete(where, len);
400	        return extractedSpanText;
401	    }
402	
403	    /**
404	     * Get last marked position of a specific tag kind (private class)
405	     */
406	    private static Object getLast(Editable text, Class kind) {
407	        Object[] objs = text.getSpans(0, text.length(), kind);
408	        if (objs.length == 0) {
409	            return null;
410	        } else {
411	            for (int i = objs.length; i > 0; i--) {
412	                if (text.getSpanFlags(objs[i - 1]) == Spannable.SPAN_MARK_MARK) {
413	                    return objs[i - 1];
414	                }
415	            }
416	            return null;
417	        }
418	    }
