453	     * Returns a list of packages that support Custom Tabs.
454	     */
455	    public static ArrayList<ResolveInfo> getCustomTabsPackages(Context context) {
456	        PackageManager pm = context.getPackageManager();
457	        // Get default VIEW intent handler.
458	        Intent activityIntent = new Intent()
459	                .setAction(Intent.ACTION_VIEW)
460	                .addCategory(Intent.CATEGORY_BROWSABLE)
461	                .setData(Uri.fromParts("http", "", null));
462	
463	        // Get all apps that can handle VIEW intents.
464	        List<ResolveInfo> resolvedActivityList = pm.queryIntentActivities(activityIntent, 0);
465	        ArrayList<ResolveInfo> packagesSupportingCustomTabs = new ArrayList<>();
466	        for (ResolveInfo info : resolvedActivityList) {
467	            Intent serviceIntent = new Intent();
468	            serviceIntent.setAction(ACTION_CUSTOM_TABS_CONNECTION);
469	            serviceIntent.setPackage(info.activityInfo.packageName);
470	            // Check if this package also resolves the Custom Tabs service.
471	            if (pm.resolveService(serviceIntent, 0) != null) {
472	                packagesSupportingCustomTabs.add(info);
473	            }
474	        }
475	
476	        return packagesSupportingCustomTabs;
477	    }
