523	    /**
524	     * Check if time represented as minutes since midnight is between two other times.
525	     * <p>
526	     * If {@code initialTime} is after {@code finalTime}, then {@code currentTime} must be between
527	     * last day's {@code initialTime} and this day's {@code finalTime} or this day's {@code initialTime}
528	     * and next day's {@code finalTime}
529	     */
530	    public static boolean isTimeBetweenTwoTimes(long initialTime, long finalTime, long currentTime) {
531	        if (finalTime < initialTime) {
532	            finalTime += TimeUnit.DAYS.toMinutes(1);
533	        }
534	
535	        if (currentTime < initialTime) {
536	            currentTime += TimeUnit.DAYS.toMinutes(1);
537	        }
538	
539	        return initialTime <= currentTime && currentTime < finalTime;
540	    }
