24	public class HtmlFormatter {
25	
26	    private HtmlFormatter() {
27	    }
28	
29	    public static Spanned formatHtml(@NonNull final HtmlFormatterBuilder builder) {
30	        return formatHtml(
31	            builder.getHtml(), builder.getImageGetter(), builder.getClickableTableSpan(),
32	            builder.getDrawTableLinkSpan(), new TagClickListenerProvider() {
33	                @Override public OnClickATagListener provideTagClickListener() {
34	                    return builder.getOnClickATagListener();
35	                }
36	            }, builder.getIndent(),
37	            builder.isRemoveTrailingWhiteSpace()
38	        );
39	    }
40	
41	    interface TagClickListenerProvider {
42	        OnClickATagListener provideTagClickListener();
43	    }
44	
45	    public static Spanned formatHtml(@Nullable String html, ImageGetter imageGetter, ClickableTableSpan clickableTableSpan, DrawTableLinkSpan drawTableLinkSpan, TagClickListenerProvider tagClickListenerProvider, float indent, boolean removeTrailingWhiteSpace) {
46	        final HtmlTagHandler htmlTagHandler = new HtmlTagHandler();
47	        htmlTagHandler.setClickableTableSpan(clickableTableSpan);
48	        htmlTagHandler.setDrawTableLinkSpan(drawTableLinkSpan);
49	        htmlTagHandler.setOnClickATagListenerProvider(tagClickListenerProvider);
50	        htmlTagHandler.setListIndentPx(indent);
51	
52	        html = htmlTagHandler.overrideTags(html);
53	
54	        Spanned formattedHtml;
55	        if (removeTrailingWhiteSpace) {
56	            formattedHtml = removeHtmlBottomPadding(Html.fromHtml(html, imageGetter, new WrapperContentHandler(htmlTagHandler)));
57	        } else {
58	            formattedHtml = Html.fromHtml(html, imageGetter, new WrapperContentHandler(htmlTagHandler));
59	        }
60	
61	        return formattedHtml;
62	    }
63	
64	    /**
65	     * Html.fromHtml sometimes adds extra space at the bottom.
66	     * This methods removes this space again.
67	     * See https://github.com/SufficientlySecure/html-textview/issues/19
68	     */
69	    @Nullable
70	    private static Spanned removeHtmlBottomPadding(@Nullable Spanned text) {
71	        if (text == null) {
72	            return null;
73	        }
74	
75	        while (text.length() > 0 && text.charAt(text.length() - 1) == '\n') {
76	            text = (Spanned) text.subSequence(0, text.length() - 1);
77	        }
78	        return text;
79	    }
80	}
